"use client";

import { useContent, withBasePath } from "@/lib/site-data";

type ExtraPage = { id?: string; label?: string; route?: string };

/*
 * Pages the dealer creates in Fivora (privacy policy, warranty terms, ...). Fivora writes them into
 * site-data.json `additionalPages`; the template must link to them. Per the strict contract the list
 * container stays mounted even when empty (it then has no margin, so it takes no space).
 * Plain <a> (not next/link): these pages are generated by Fivora, not part of our static export.
 */
export function AdditionalPages({ className, linkClassName }: { className?: string; linkClassName?: string }) {
  const raw = useContent().additionalPages;
  const pages = (Array.isArray(raw) ? raw : []) as ExtraPage[];
  return (
    <ul data-preview-list-path="additionalPages" className={pages.length ? className : undefined}>
      {pages.map((page, index) => (
        <li
          key={page.id ?? index}
          data-preview-item-path={`additionalPages[${index}]`}
          data-preview-field-path={`additionalPages[${index}]`}
        >
          <a
            href={withBasePath(page.route || "/")}
            className={linkClassName}
            data-preview-field-path={`additionalPages[${index}].label`}
          >
            {page.label}
          </a>
        </li>
      ))}
    </ul>
  );
}
